div.script:
let games=[];


const GAME_URL =
"https://raw.githubusercontent.com/CowGoMoo357/htmlgamesrepos/main/games.json";




async function loadGames(){


try{


let response =
await fetch(GAME_URL);



let data =
await response.json();



games =
data.games;



displayGames(games);



}

catch(e){

document.getElementById("games")
.innerHTML =
"Failed loading games";

}


}





function displayGames(list){


let box =
document.getElementById("games");


box.innerHTML="";



list.forEach(game=>{


let card =
document.createElement("div");


card.className="card";



card.innerHTML = `

<div>

<b>${game.name}</b>

<br>

<small>
${game.category || "Game"}
</small>

</div>


<button class="play">
Play
</button>

`;



card.querySelector("button")
.onclick=()=>{


fetch(game.url)

.then(r=>r.text())

.then(code=>{


let tab =
window.open(
"data:text/html;charset=utf-8,"
+
encodeURIComponent(code)
);


});


};



box.appendChild(card);


});


}




function filterGames(){


let query =
document
.getElementById("search")
.value
.toLowerCase();



displayGames(

games.filter(
g =>
g.name
.toLowerCase()
.includes(query)
)

);


}




loadGames();
